   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 11 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK, COVER_SECTION_CODE, DISABILITY_TYPE_CODE
   hashdiff    : SAT_CLAIM_DISABILITY_HEAD_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 2 attribute/run pair(s) with more than one writer, of
   which 2 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     DISABILITY_DESCRIPTION                 opus_health_v2         5 writer(s), of which 5 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [same-table]
     DISABILITY_PERCENTAGE                  opus_health_v2         3 writer(s), of which 3 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [same-table]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , coalesce(nullif(trim(COVER_SECTION), ''), '') as COVER_SECTION_CODE
        , 'TTD' as DISABILITY_TYPE_CODE
        , TTD_DISABILTY as DISABILITY_DESCRIPTION
        , PTD_PERCENTAGE as DISABILITY_PERCENTAGE
        , PPD_DESC_FUNC_LOSS as FUNCTIONAL_LOSS_DESCRIPTION
        , TTD_APPROVED_DAYS as APPROVED_DAYS_COUNT
        , TTD_DISABLE_DURATION as DISABILITY_DURATION
        , TTD_FITNESS_DATE as FITNESS_CERTIFIED_DATE
        , TTD_INJ_DATE as INJURY_DATE
        , TTD_LEAVE_DURATION as LEAVE_DURATION
        , TTD_LEAVE_FROM as LEAVE_FROM_DATE
        , TTD_LEAVE_TO as LEAVE_TO_DATE
        , TTD_WEEK_BENEFIT as WEEKLY_BENEFIT_AMOUNT
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        COVER_SECTION_CODE,
        DISABILITY_TYPE_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then DISABILITY_DESCRIPTION end) as DISABILITY_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then DISABILITY_PERCENTAGE end) as DISABILITY_PERCENTAGE,
        max(case when SOURCE_RUN = 'opus_health_v2' then FUNCTIONAL_LOSS_DESCRIPTION end) as FUNCTIONAL_LOSS_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then APPROVED_DAYS_COUNT end) as APPROVED_DAYS_COUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then DISABILITY_DURATION end) as DISABILITY_DURATION,
        max(case when SOURCE_RUN = 'opus_health_v2' then FITNESS_CERTIFIED_DATE end) as FITNESS_CERTIFIED_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then INJURY_DATE end) as INJURY_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LEAVE_DURATION end) as LEAVE_DURATION,
        max(case when SOURCE_RUN = 'opus_health_v2' then LEAVE_FROM_DATE end) as LEAVE_FROM_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LEAVE_TO_DATE end) as LEAVE_TO_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then WEEKLY_BENEFIT_AMOUNT end) as WEEKLY_BENEFIT_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK, COVER_SECTION_CODE, DISABILITY_TYPE_CODE
),

hashed as (
    select
        *,
        case when COVER_SECTION_CODE is not null or DISABILITY_TYPE_CODE is not null or DISABILITY_DESCRIPTION is not null or DISABILITY_PERCENTAGE is not null or FUNCTIONAL_LOSS_DESCRIPTION is not null or APPROVED_DAYS_COUNT is not null or DISABILITY_DURATION is not null or FITNESS_CERTIFIED_DATE is not null or INJURY_DATE is not null or LEAVE_DURATION is not null or LEAVE_FROM_DATE is not null or LEAVE_TO_DATE is not null or WEEKLY_BENEFIT_AMOUNT is not null
                     then md5(upper(coalesce(cast(COVER_SECTION_CODE as varchar), '') || '|' || coalesce(cast(DISABILITY_TYPE_CODE as varchar), '') || '|' || coalesce(cast(DISABILITY_DESCRIPTION as varchar), '') || '|' || coalesce(cast(DISABILITY_PERCENTAGE as varchar), '') || '|' || coalesce(cast(FUNCTIONAL_LOSS_DESCRIPTION as varchar), '') || '|' || coalesce(cast(APPROVED_DAYS_COUNT as varchar), '') || '|' || coalesce(cast(DISABILITY_DURATION as varchar), '') || '|' || coalesce(cast(FITNESS_CERTIFIED_DATE as varchar), '') || '|' || coalesce(cast(INJURY_DATE as varchar), '') || '|' || coalesce(cast(LEAVE_DURATION as varchar), '') || '|' || coalesce(cast(LEAVE_FROM_DATE as varchar), '') || '|' || coalesce(cast(LEAVE_TO_DATE as varchar), '') || '|' || coalesce(cast(WEEKLY_BENEFIT_AMOUNT as varchar), '')))
                end as SAT_CLAIM_DISABILITY_HEAD_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_DISABILITY_HEAD_HASHDIFF is not null
